package app.referencecanvas.core

import android.content.Context
import androidx.room.Room
import androidx.room.testing.MigrationTestHelper
import androidx.test.core.app.ApplicationProvider
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import app.referencecanvas.core.database.AppDatabase
import app.referencecanvas.core.database.Migrations
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith

/**
 * Guards the schema history. It reads the exported schema JSON in app/schemas (generated by the first build;
 * commit it). When the schema version is bumped: add a Migration to [Migrations.ALL], raise [CURRENT_VERSION],
 * and add a test that migrates from the previous version with data in it.
 */
@RunWith(AndroidJUnit4::class)
class MigrationTest {
    @get:Rule
    val helper = MigrationTestHelper(InstrumentationRegistry.getInstrumentation(), AppDatabase::class.java)

    @Test
    fun currentSchemaOpensWithTheRegisteredMigrations() {
        helper.createDatabase(DB_NAME, CURRENT_VERSION).close()

        val context = ApplicationProvider.getApplicationContext<Context>()
        Room.databaseBuilder(context, AppDatabase::class.java, DB_NAME)
            .addMigrations(*Migrations.ALL)
            .build()
            .apply { openHelper.writableDatabase.close(); close() }
    }

    private companion object {
        const val DB_NAME = "migration-test"
        const val CURRENT_VERSION = 1
    }
}
